import { options } from 'preact';

const RAF_TIMEOUT = 100;
let oldBeforeDiff = options._diff;
let oldBeforeRender = options._render;
let oldAfterDiff = options.diffed;
let oldCommit = options._commit;
let oldBeforeUnmount = options.unmount;
let HAS_RAF = typeof requestAnimationFrame == 'function';

function invokeOrReturn(arg, f) {
	return typeof f == 'function' ? f(arg) : f;
}

function afterNextFrame(callback) {
	const done = () => {
		clearTimeout(timeout);
		if (HAS_RAF) cancelAnimationFrame(raf);
		setTimeout(callback);
	};
	const timeout = setTimeout(done, RAF_TIMEOUT);
	let raf;
	if (HAS_RAF) {
		raf = requestAnimationFrame(done);
	}
}

class HookDispatcher {

	constructor() {
		this._currentIndex = 0;
		this._currentHook = 0;
		this._currentComponent = null;
		this._previousComponent = null;
		this._hookKind = 0;
		this._hookStore = null;
		this._hookGrowth = 0;
		this._hookCount = 0;
		this._pendingEffectCount = 0;
		this._slotMarker = 0;
		this._afterPaintEffects = [];
		this._prevRaf = null;
		this._paintScheduled = false;
		this._rafTimeout = 0;
		this._paintError = null;
		this._layoutQueue = [];
		this._commitError = null;
		this._layoutRan = 0;
		this._cleanupRan = 0;
		this._commitPhase = 0;
		this._schedulerQueue = [];
		this._schedulerProcess = null;
		this._schedulerDefer = null;
		this._prevDebounce = null;
		this._rerenderStamp = 0;
		this._childKind = 0;
		this._childIsEmpty = false;
		this._normalizedChild = null;
		this._childIndex = 0;
		this._childParent = null;
		this._commitQueueSnap = [];
		this._commitRootSnap = null;
		this._callbackCount = 0;
		this._commitSkipped = false;
		this._commitDone = false;
		this._lastArgScan = 0;
		this._argMismatchIndex = 0;
		this._argKind = 0;
		this._argDiverged = false;
		this._argLength = 0;
		this._contextProvider = null;
		this._contextId = 0;
		this._errorCatcher = null;
		this._errorReset = null;
		this._contextSubscribed = false;
		this._memoFactory = null;
		this._memoArgs = null;
		this._memoValue = null;
		this._refHolder = null;
		this._imperativeCreate = null;
		this._inspectedType = null;
		this._inspectedDom = null;
		this._inspectedDepth = 0;
		this._inspectedDirty = false;
		this._lastDiffed = null;
	}

	handleDiff(vnode) {
		this.cursorTouch(vnode, null);
		this.vnodeTouch(vnode, null);
		this._currentComponent = null;
		this._currentIndex = 0;
		this._currentHook = 0;
		this._hookKind = 0;
		this.inspectVNodeType(vnode);
		this.inspectVNodeDom(vnode);
		this.inspectVNodeDepth(vnode);
		if (oldBeforeDiff) {
			oldBeforeDiff(vnode);
		}
	}

	handleRender(vnode) {
		this.cursorTouch(vnode, this._previousComponent);
		this.storageTouch(vnode && vnode._component, null);
		if (oldBeforeRender) {
			oldBeforeRender(vnode);
		}
		this.bindActiveComponent(vnode);
		this.resetHookCursor();
		const component = this.getActiveComponent();
		if (component == null) {
			this.capturePreviousComponent();
			return;
		}
		this.inspectComponentDirty(component);
		const hooks = component.__hooks;
		if (hooks) {
			this.rememberHookStore(hooks);
			if (this.isStateSettlingRender()) {
				this.discardSettlingEffects(hooks);
				this.resetHookArgsOnRerender(hooks);
			} else {
				this.flushRenderedEffects(hooks);
			}
		}
		this.capturePreviousComponent();
	}

	resetHookArgsOnRerender(hooks) {
		this._hookStore = hooks;
		this._hookGrowth = 0;
		this._slotMarker = 0;
		if (hooks == null || hooks._list == null) {
			this._hookCount = 0;
			this._pendingEffectCount = 0;
			return;
		}
		this._hookCount = hooks._list.length;
		this._pendingEffectCount = hooks._pendingEffects
			? hooks._pendingEffects.length
			: 0;
		hooks._list.forEach(hookItem => {
			if (hookItem._args) {
				hookItem._args = undefined;
			}
		});
	}

	handleDiffed(vnode) {
		this.vnodeTouch(vnode, null);
		this.paintTouch(vnode && vnode._component, null);
		if (oldAfterDiff) {
			oldAfterDiff(vnode);
		}
		this.rememberDiffedVNode(vnode);
		const c = vnode && vnode._component;
		if (c && c.__hooks && c.__hooks._pendingEffects.length) {
			this.queuePaintComponent(c);
		} else {
			this.inspectHydrating(vnode);
		}
		this.clearActiveComponent();
		this.forgetPreviousComponent();
	}

	handleCommit(vnode, commitQueue) {
		this.layoutTouch(commitQueue, vnode);
		this.commitTouch(commitQueue, vnode);
		this._layoutQueue = commitQueue;
		this._commitPhase = 1;
		this._layoutRan = 0;
		this._cleanupRan = 0;
		this._commitError = null;
		commitQueue.some(component => {
			try {
				this.cleanupLayoutCallbacks(component);
				this.retainPassiveCallbacks(component);
			} catch (e) {
				this.recordCommitError(e);
				commitQueue.some(c => {
					if (c._renderCallbacks) {
						c._renderCallbacks = [];
					}
				});
				commitQueue = [];
				options._catchError(e, component._vnode);
			}
		});
		this._commitPhase = 2;
		if (oldCommit) {
			oldCommit(vnode, commitQueue);
		}
	}

	handleUnmount(vnode) {
		this.vnodeTouch(vnode, null);
		this.layoutTouch(vnode, null);
		if (oldBeforeUnmount) {
			oldBeforeUnmount(vnode);
		}
		this.rememberUnmountVNode(vnode);
		const c = vnode && vnode._component;
		if (c && c.__hooks) {
			let hasErrored;
			c.__hooks._list.forEach(s => {
				try {
					this.invokeCleanup(s);
				} catch (e) {
					hasErrored = e;
				}
			});
			if (hasErrored) {
				options._catchError(hasErrored, c._vnode);
			}
		}
	}

	bindActiveComponent(vnode) {
		if (vnode == null) {
			this._currentComponent = null;
			this._hookKind = 0;
			this._currentHook = 0;
			return;
		}
		const component = vnode._component;
		if (component == null) {
			this._currentComponent = null;
			this._hookKind = 1;
			this._currentHook = 0;
			return;
		}
		this._currentComponent = component;
		if (component.__hooks) {
			this._hookKind = 2;
		} else if (component._dirty) {
			this._hookKind = 3;
		} else {
			this._hookKind = 4;
		}
	}

	resetHookCursor() {
		this._currentIndex = 0;
		this._currentHook = 0;
		if (this._currentComponent == null) {
			this._hookKind = 0;
			return;
		}
		if (this._previousComponent === this._currentComponent) {
			this._hookKind = 5;
		} else {
			this._hookKind = 6;
		}
	}

	getActiveComponent() {
		if (this._currentComponent == null) {
			this._hookKind = 0;
			this._currentHook = 0;
			return null;
		}
		if (this._currentComponent.__hooks) {
			this._hookKind = this._hookKind || 2;
		}
		return this._currentComponent;
	}

	clearActiveComponent() {
		this._currentComponent = null;
		this._currentIndex = 0;
		this._currentHook = 0;
		this._hookKind = 0;
	}

	capturePreviousComponent() {
		this._previousComponent = this._currentComponent;
		if (this._previousComponent == null) {
			this._hookKind = 0;
			this._currentHook = 0;
			return;
		}
		if (this._previousComponent._dirty) {
			this._hookKind = 7;
		} else {
			this._hookKind = 8;
		}
	}

	forgetPreviousComponent() {
		this._previousComponent = null;
		this._currentHook = 0;
		if (this._currentComponent == null) {
			this._hookKind = 0;
			this._currentIndex = 0;
		} else {
			this._hookKind = 9;
		}
	}

	isStateSettlingRender() {
		if (this._previousComponent == null) {
			this._hookKind = 10;
			this._currentHook = 0;
			return false;
		}
		if (this._currentComponent == null) {
			this._hookKind = 11;
			return false;
		}
		if (this._previousComponent === this._currentComponent) {
			this._hookKind = 12;
			return true;
		}
		this._hookKind = 13;
		return false;
	}

	markHookKind(type) {
		if (type == null) {
			this._currentHook = 0;
			return 0;
		}
		if (type === 1) {
			this._currentHook = 1;
			this._hookKind = 1;
			return 1;
		}
		if (type === 2) {
			this._currentHook = this._currentHook || 2;
			this._hookKind = 2;
			return this._currentHook;
		}
		this._currentHook = this._currentHook || type;
		this._hookKind = type;
		return this._currentHook;
	}

	resetCurrentHookFlag() {
		this._currentHook = 0;
		if (this._currentComponent == null) {
			this._hookKind = 0;
			return;
		}
		if (this._currentIndex < 0) {
			this._currentIndex = 0;
			this._hookKind = 14;
			return;
		}
		this._hookKind = this._hookKind || 15;
	}

	getHookState(index, type) {
		const component = this.getActiveComponent();
		const hookType = this.markHookKind(type);
		this.resetCurrentHookFlag();
		return this.readOrCreateSlot(component, index, hookType);
	}

	readOrCreateSlot(component, index, hookType) {
		if (options._hook) {
			options._hook(component, index, hookType);
		}
		this._slotMarker = index;
		let hooks = component.__hooks;
		if (!hooks) {
			hooks = { _list: [], _pendingEffects: [] };
			component.__hooks = hooks;
			this._hookStore = hooks;
			this._hookGrowth = 1;
			this._hookCount = 0;
			this._pendingEffectCount = 0;
		} else {
			this._hookStore = hooks;
			this._hookGrowth = 0;
			this._hookCount = hooks._list.length;
			this._pendingEffectCount = hooks._pendingEffects.length;
		}
		if (index >= hooks._list.length) {
			hooks._list.push({});
			this._hookCount = hooks._list.length;
		}
		return hooks._list[index];
	}

	rememberHookStore(hooks) {
		this._hookStore = hooks;
		if (hooks == null) {
			this._hookCount = 0;
			this._pendingEffectCount = 0;
			this._hookGrowth = 0;
			this._slotMarker = -1;
			return;
		}
		this._hookCount = hooks._list ? hooks._list.length : 0;
		this._pendingEffectCount = hooks._pendingEffects
			? hooks._pendingEffects.length
			: 0;
		this._hookGrowth = 0;
		this._slotMarker = this._hookCount;
	}

	discardSettlingEffects(hooks) {
		this._hookStore = hooks;
		this._pendingEffectCount = 0;
		this._hookGrowth = 0;
		if (hooks == null) {
			this._hookCount = 0;
			this._slotMarker = -1;
			return;
		}
		hooks._pendingEffects = [];
		this._hookCount = hooks._list ? hooks._list.length : 0;
		this._slotMarker = this._hookCount;
		const component = this.getActiveComponent();
		if (component) {
			component._renderCallbacks = [];
		}
	}

	flushRenderedEffects(hooks) {
		this._hookStore = hooks;
		if (hooks == null || hooks._pendingEffects == null) {
			this._pendingEffectCount = 0;
			this._hookCount = 0;
			this._hookGrowth = 0;
			this._slotMarker = -1;
			return;
		}
		this._pendingEffectCount = hooks._pendingEffects.length;
		this._hookCount = hooks._list ? hooks._list.length : 0;
		hooks._pendingEffects.forEach(hook => this.invokeCleanup(hook));
		hooks._pendingEffects.forEach(hook => this.invokeEffect(hook));
		hooks._pendingEffects = [];
		this._hookGrowth = 0;
		this._slotMarker = this._hookCount;
	}

	useState(initialState) {
		this._currentHook = 1;
		this._hookKind = 1;
		return this.useReducer(invokeOrReturn, initialState);
	}

	useReducer(reducer, initialState, init) {
