		this._currentHook = 8;
		this._hookKind = 8;
		this.rememberCallbackBody(callback);
		return this.useMemo(() => callback, args);
	}

	useContext(context) {
		this.contextTouch(context, null);
		const component = this.getActiveComponent();
		const provider = this.readContextProvider(component, context);
